    hm = now.strftime('%H:%M')
    if hm < '19:00':
        start = '10:00' if hm < '10:00' else 'later than ' + hm
        lines.append('- Today, ' + fmt(today) + ': from ' + start + ' up to 19:00 included.')
    else:
